                                stridet);

        // 3. apply the Householder reflector to A as a rank-2 update:
        // A = A - v*w' - w*v'
        rocblasCall_syr2_her2<T>(handle, uplo, n - 1 - j, scalars, A,
                                 shiftA + idx2D(j + 1, j, lda), 1, strideA, tau, j, 1, strideP,
