for(rocblas_int j = 0; j < n - 1; ++j)
{
    const rocblas_int nn = n - j;
    const size_t lmemsize = ((256 / props.warpSize) + 2 * nn + 1 + nn * nn) * sizeof(T);
    if(lmemsize <= props.sharedMemPerBlock && nn <= xxTD2_SSKER_MAX_N)
